compliant:
import { Schema as S } from "effect"

export const TemplateTitle = S.NonEmptyString.check(
  S.isMaxLength(120)
)

export const DeliveryTemplate = S.Struct({
  id: S.String,
  title: TemplateTitle,
  channel: S.Literals(["email", "sms", "push"]),
  enabled: S.Boolean,
  content: S.Struct({
    subject: S.String,
    body: S.String
  })
})

export type DeliveryTemplate = typeof DeliveryTemplate.Type

export const decodeDeliveryTemplate = S.decodeUnknownEffect(DeliveryTemplate)

export const summarizeTemplate = (template: DeliveryTemplate): string => {
  const status = template.enabled ? "enabled" : "disabled"
  return `${template.title} (${template.channel}, ${status})`
}
